SELECT event AS Event,coalesce(toString(properties.surface),'server') AS Surface,coalesce(toString(properties.app_version),'n/a') AS Version,count() AS Events,uniqExact(person_id) AS People,max(timestamp) AS Last_seen FROM events WHERE (properties.environment = 'production' AND properties.product = 'studio') AND {filters} GROUP BY Event,Surface,Version ORDER BY Last_seen DESC LIMIT 150
